  "Witch Potion": {"id":"item_consumable_spellpowerpotion_t02","kind":"consumable","cat":"Potion","rarity":"Common","desc":"A brew that increases spell power by 5 for 60 minutes.\n\nEffect persists through death.","effect":"Spell Power +5 for 60 minutes","recipe":{"station":"Alchemy Table","time":20,"inputs":[["Sacred Grapes",60],["Snow Flower",60],["Fish Bone",1],["Empty Glass Bottle",1]],"unlock":["Athenaeum"]},"drops":[{"name":"Servant hunt: Venom Mixing Outpost","rate":0.1,"kind":"loot"}],"icon":"/images/icons/stunlock_icon_glassbottle_spellbrew_t02.webp"},
  "Wood": {"id":"item_ingredient_wood_standard","kind":"material","cat":"Mineral","rarity":"Common","desc":"Commonly used in construction as well as crafting.\n\nRefined at a Sawmill.","drops":[{"name":"Tree","rate":1,"kind":"loot","n":26526}],"icon":"/images/icons/poneti_icon_res_24.webp"},
  "Wool Thread": {"id":"item_ingredient_thread_wool","kind":"material","cat":"Tailoring","rarity":"Common","desc":"Tailoring components are used for crafting clothes, armour and cloaks.\n\nProduced at a Loom.","recipe":{"station":"Loom","time":30,"inputs":[["Cloth",1],["Coarse Thread",4]],"unlock":["Christina the Sun Priestess"]},"drops":[{"name":"Scarecrow","rate":1,"kind":"npc"},{"name":"Knight","rate":0.3,"kind":"npc","n":65,"layer":"npc:char_churchoflight_knight_2h"},{"name":"Viper","rate":0.3,"kind":"npc","n":56,"layer":"npc:char_blackfang_viper"},{"name":"Dreadcleaver","rate":0.3,"kind":"npc","n":50,"layer":"npc:char_blackfang_venomblade"},{"name":"Church Cleric","rate":0.3,"kind":"npc","n":45,"layer":"npc:char_churchoflight_cleric"},{"name":"Striker","rate":0.3,"kind":"npc","n":44,"layer":"npc:char_blackfang_striker"}],"icon":"/images/icons/fantasyicon_resourceandcraftaddon__56_.webp"}
