  "Bane the Shadowblade": {"id":"char_undead_infiltrator_vblood","lv":50,"vblood":true,"unit":"Human","desc":"Once a formidable swordsman and legendary graverobber, Bane was caught by the Cult of the Damned during one of his many heists. Seeing the benefit of his talent for infiltration, instead of killing him, they corrupted him into a servant of undeath. It’s said that his clandestine abilities were crucial in the capture and corruption of the Iron Mine over the Militia.","stats":{"pp":54.2,"sp":54.2,"dr":0,"physRes":0,"spellRes":0,"fireRes":50},"abilities":["Primary Attack","Shadow Step","Knife Throw"],"drops":[["Unsullied Heart",1],["Jewel",0.35],["Regular Amethyst",0.167],["Regular Emerald",0.167],["Regular Miststone",0.167],["Regular Ruby",0.167],["Regular Sapphire",0.167],["Regular Topaz",0.167]],"spawns":[[-1137,-553]]},
