  "Baron du Bouchon the Sommelier": {"id":"char_churchoflight_sommelier_vblood","lv":70,"vblood":true,"unit":"Human","desc":"Formerly a traveling swordsman-for-hire, the good baron earned his title of Grand Sommelier after winning a tasting contest hosted by the Church of Luminance. His abilities were so extraordinary, it’s said that he can name the ingredients, their ages, and their place of origin with only a sip of brew. Though his new position offers him all the worldly goods he could desire, those who know him well suspect he may miss the taste of blood on the tip of his blade most of all.","stats":{"pp":80.6,"sp":80.6,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Barrel Roll","Sanguine Coil","Flurry"],"drops":[["Exquisite Heart",1],["Jewel",0.35],["Gold Jewelry",0.273],["Ancestral Weapon",0.25],["Flawless Amethyst",0.167],["Flawless Emerald",0.167],["Flawless Miststone",0.167],["Flawless Ruby",0.167],["Flawless Sapphire",0.167],["Flawless Topaz",0.167]],"spawns":[[-2196,-775]]},
