  "Errol the Stonebreaker": {"id":"char_bandit_stonebreaker_vblood","lv":20,"vblood":true,"unit":"Human","desc":"A brutal mining foreman, just as adept at crushing stone as he is crushing bone. Not even his incredible eye for recovering and refining metals was enough to stop him from getting run out of civilised society. His violent rage makes a fine motivator for the miners.","stats":{"pp":24.4,"sp":24.4,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Secondary Attack","Reinforcement"],"drops":[["Unsullied Heart",0.25],["Crude Amethyst",0.033],["Crude Emerald",0.033],["Crude Miststone",0.033],["Crude Ruby",0.033],["Crude Sapphire",0.033],["Crude Topaz",0.033]],"spawns":[[-1549,-1464]]},
