  "Finn the Fisherman": {"id":"char_bandit_fisherman_vblood","lv":32,"vblood":true,"unit":"Human","desc":"Finn is a legendary fisherman who hails from the rocky shores of Silverlight Hills. Caught fishing in the Church of Luminance’s “sacred” waters, he was set to be executed by live burial at sea. The fisherman emerged from the depths, mysterious and miraculously alive, and went into hiding in the safety of the lawless lands of the Farbane Woods.","stats":{"pp":34.5,"sp":34.5,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Fish Hook","Secondary Attack","Serpent Feed","Fishing Blowfish","Fishing Piranhas","Fishing Old Boot"],"drops":[["Unsullied Heart",0.25],["Crude Amethyst",0.033],["Crude Emerald",0.033],["Crude Miststone",0.033],["Crude Ruby",0.033],["Crude Sapphire",0.033],["Crude Topaz",0.033]],"spawns":[[-827,-1213]]},
  "Foulrot the Soultaker": {"id":"char_undead_zealouscultist_vblood","lv":63,"vblood":true,"unit":"Human","desc":"A mad cultist that claims to be the vessel of his decapitated horse, ‘Foulrot the Soultaker.’ He also claims his blades take their victims straight to ‘The Great Darkness’, an effort to feed or please some infernal power. Whether or not there’s truth to his claims, his headcount is undeniable.","stats":{"pp":70.9,"sp":70.9,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Summon Ghosts","Shadow Meld","Camouflage"],"drops":[["Unsullied Heart",0.8],["Jewel",0.35],["Ancestral Weapon",0.25],["Exquisite Heart",0.2],["Flawless Amethyst",0.042],["Flawless Emerald",0.042],["Flawless Miststone",0.042],["Flawless Ruby",0.042],["Flawless Sapphire",0.042],["Flawless Topaz",0.042]],"spawns":[[-615,-78]]},
  "Frostmaw the Mountain Terror": {"id":"char_wendigo_vblood","lv":53,"vblood":true,"unit":"Beast","desc":"An unspeakable horror that lurks in the snowy corridors of the Hallowed Mountains. Some say it used to be a simple woodsman. Most don’t dare invoke its name at all.","stats":{"pp":57.9,"sp":57.9,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Frost Nova","Ice Beam","Leap Attack"],"drops":[["Unsullied Heart",0.8],["Jewel",0.35],["Ancestral Weapon",0.25],["Exquisite Heart",0.2],["Flawless Amethyst",0.042],["Flawless Emerald",0.042],["Flawless Miststone",0.042],["Flawless Ruby",0.042],["Flawless Sapphire",0.042],["Flawless Topaz",0.042]],"spawns":[[-716,-1155]]},
  "Gaius the Cursed Champion": {"id":"char_undead_arenachampion_vblood","lv":55,"vblood":true,"unit":"Human","desc":"Gaius was a skilled militia captain and a famous gladiator. Annoyed at Gaius popularity competing with his own, as well as that of the Church of Luminance, Raziel arranged for his defeat by way of a cursed blade. The event was devastating, and the Colosseum has been abandoned ever since… however, it is said that even today, issuing a challenge in the abandoned arena will be met with an answer.","stats":{"pp":60.4,"sp":60.4,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Fadestrike","Windslash","Disengage","Leap Strike","Charge","Sweeping Strike","Javelin","Counter Strike","Chains Of Death"],"drops":[["Unsullied Heart",1],["Jewel",0.35],["Regular Amethyst",0.167],["Regular Emerald",0.167],["Regular Miststone",0.167],["Regular Ruby",0.167],["Regular Sapphire",0.167],["Regular Topaz",0.167]],"spawns":[[-992,-513]]},
