  "General Cassius the Betrayer": {"id":"char_vampire_highlord_vblood","lv":57,"vblood":true,"unit":"PvEVampire","desc":"Once a highly skilled and respected officer within the ranks of the Church of Luminance, Cassius served as a powerful paladin who led a troupe tasked with hunting down Dracula himself. His mission ended in failure, overpowered by the Immortal King and forced into servitude. With the dark influence of his sentient blade, Nightfall Edge, affecting his mind, Cassius now serves as a loyal general for the Legion of Noctum.","stats":{"pp":63,"sp":63,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Corpse Storm","Whirlwind","Great Cleaver","Arctic Leap","Blood Rage","Raise Dead","Corrupted Skull"],"drops":[["Unsullied Heart",0.8],["Jewel",0.35],["Ancestral Weapon",0.25],["Exquisite Heart",0.2],["Flawless Amethyst",0.042],["Flawless Emerald",0.042],["Flawless Miststone",0.042],["Flawless Ruby",0.042],["Flawless Sapphire",0.042],["Flawless Topaz",0.042]],"spawns":[[-649,-320]]},
  "General Elena the Hollow": {"id":"char_vampire_iceranger_vblood","lv":53,"vblood":true,"unit":"PvEVampire","desc":"Elena was once a talented weaver, a wife, a mother, and friend. Now she is none of those things. When Dracula’s forces descended on her village and harvested its people, she hid in the chaos and witnessed the horror first-hand. Discovered by the Immortal King himself, he saw an opportunity to twist a suffering creature to his whim. He shaped her into an ice-cold killing machine, a perfect servant for the Legion of Noctum.","stats":{"pp":57.9,"sp":57.9,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Rain of Bolts","Veil of Frost","Cold Snap","Ice Nova","Tower Of Frost","Blood Mend"],"drops":[["Unsullied Heart",0.8],["Jewel",0.35],["Ancestral Weapon",0.25],["Exquisite Heart",0.2],["Flawless Amethyst",0.042],["Flawless Emerald",0.042],["Flawless Miststone",0.042],["Flawless Ruby",0.042],["Flawless Sapphire",0.042],["Flawless Topaz",0.042]],"spawns":[[-700,-714]]},
  "General Valencia the Depraved": {"id":"char_vampire_bloodknight_vblood","lv":84,"vblood":true,"unit":"PvEVampire","desc":"Valencia was once a human baroness, part of an affluent noble family from before the great war. Always hungry for power, ambitious, and utterly without moral tethers, she saw the rise of Dracula and his legions as an opportunity to surpass her human limitations and become something greater. Impressed with her utter depravity, Dracula granted the baroness’ wish. Valencia now serves as a vicious general of the Legion of Noctum.","stats":{"pp":100.9,"sp":100.9,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Hooking Spear","A Thousand Spears","Spear Twirl","Summon Crimson Maiden","Arctic Leap"],"drops":[["Unsullied Heart",0.8],["Jewel",0.741],["Exquisite Heart",0.2],["Ancestral Weapon",0.05],["Flawless Amethyst",0.042],["Flawless Emerald",0.042],["Flawless Miststone",0.042],["Flawless Ruby",0.042],["Flawless Sapphire",0.042],["Flawless Topaz",0.042],["Onyx Tear",0.037]],"spawns":[[-532,-347]]},
