  "Grayson the Armourer": {"id":"char_bandit_stalker_vblood","lv":27,"vblood":true,"unit":"Human","desc":"The working arm and logistical mastermind of the bandit forces, Grayson is the backbone of their operation. As the quartermaster of a band of chaotic outlaws, murderers, and thieves, he’s the stern voice of reason that keeps their gang well fed and well equipped.","stats":{"pp":30,"sp":30,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Primary Attack","Projectile","Secondary Attack","Reinforcement","Spike Trap"],"drops":[["Unsullied Heart",1],["Jewel",0.35],["Crude Amethyst",0.042],["Crude Emerald",0.042],["Crude Miststone",0.042],["Crude Ruby",0.042],["Crude Sapphire",0.042],["Crude Topaz",0.042]],"spawns":[[-1683,-1402]]},
  "Grethel the Glassblower": {"id":"char_militia_glassblower_vblood","lv":50,"vblood":true,"unit":"Human","desc":"A true artist with a deep love for the process of creation. She thinks of herself much like she thinks of her glass. It is beautiful and practical, chaotic and tame, strong and yet delicate. In the same way, her style of glassblowing is methodical and daring. While she is a master of her craft, she wears many savage burn scars for her haphazard approach.","stats":{"pp":54.2,"sp":54.2,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Cyclone","Glass Rain","Arctic Leap","Primary Attack","Deep Breath","Mirror Shield"],"drops":[["Unsullied Heart",1],["Jewel",0.35],["Regular Amethyst",0.042],["Regular Emerald",0.042],["Regular Miststone",0.042],["Regular Ruby",0.042],["Regular Sapphire",0.042],["Regular Topaz",0.042]],"spawns":[[-1727,-357]]},
