  "Henry Blackbrew the Doctor": {"id":"char_gloomrot_theprofessor_vblood","lv":74,"vblood":true,"unit":"Human","desc":"Doctor Henry Blackbrew was once humankind’s last hope against the forces of Dracula, before the Church of Luminance came along. With their newly found faith and weapons of light, mankind turned on the Doctor for his sick methodology and pursuit of human evolution, declaring him a heretic. Banished alongside his students, he went on to found The Trancendum and began constructing a society in his image. With the help of a resource he refers to as “Blood Type E” he’s managed to maintain his youth, and keep his twisted pursuit of “progress” alive for well over 800 years.","stats":{"pp":86.3,"sp":86.3,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Imploding Orb","Multi Lazer","Electric Push","Discharge","Few Beams","Perma Beams","Many Beams"],"drops":[["Exquisite Heart",1],["Jewel",0.35],["Gold Jewelry",0.273],["Ancestral Weapon",0.25],["Flawless Amethyst",0.167],["Flawless Emerald",0.167],["Flawless Miststone",0.167],["Flawless Ruby",0.167],["Flawless Sapphire",0.167],["Flawless Topaz",0.167]],"spawns":[[-1803,38]]},
