  "Lidia the Chaos Archer": {"id":"char_bandit_chaosarrow_vblood","lv":30,"vblood":true,"unit":"Human","desc":"An adept but undisciplined archer, she lets her arrows fly and trusts that fate knows where to take them, and it works. Lidia is a force of chaos that cannot be contained, and the bandit king is happy to let her do as she likes as long as it benefits him.","stats":{"pp":32.7,"sp":32.7,"dr":0,"physRes":0,"spellRes":0,"fireRes":0},"abilities":["Chaosstorm","Camouflage","Dash","Chaosbarrage","Chaos Nuke"],"drops":[["Unsullied Heart",0.25],["Crude Amethyst",0.033],["Crude Emerald",0.033],["Crude Miststone",0.033],["Crude Ruby",0.033],["Crude Sapphire",0.033],["Crude Topaz",0.033]],"spawns":[[-1404,-1640]]},
